F('r-no-sms', 'problem', 'high', 'recipient', 'r_home', 15, 'Customer', 'tech', 'المستلم ما بيوصلوش أي حاجة من وصّلي', { short: 'المستلم ما يعرفش',
  what: 'مزوّد الرسائل في الكود متضبط «noop»، والمستلم مالوش حساب. يعني اللي حد طلبله ما يعرفش إن فيه طلب جاي ولا ميعاده ولا الكود.', why: 'التسليم كله مبني على كود بيتقال وش لوش — واللي على الباب مش معاه الكود.', ex: 'سعاد فتحت لكابتن ما تعرفوش وقالت «أنا ماطلبتش حاجة».', pol: ['CUSTOMER_007', 'DATA_003'], cur: 'الكود يخالف القاعدة (SRC-0019: noop) — والمستلم مش كيان منفصل (CUSTOMER_007 غير محقَّقة).', imp: { c: 'المشتري لازم يبلّغ بنفسه', m: '—', k: 'انتظار عند الباب', w: 'فشل تسليم أكتر' }, fin: 'كل رحلة بتفشل ليها تكلفة مشوار — ومين يتحملها غير محسوم (FDR-0002).', risk: 'مرتفع — CFL-0011', fix: 'بعد تشغيل مزوّد الرسائل فعلًا: رسالة للمستلم فيها اسم المشتري والميعاد والكود، ومن غير سعر لو «هدية».', alt1: 'الكابتن يكلّم المستلم قبل الوصول بدقيقتين.', alt2: '—', need: N(1, 0, 0, 1), src: 'SRC-0019 · CFL-0011 · CUSTOMER_007' });
F('r-code-gap', 'problem', 'high', 'recipient', 'r_home', 17, 'Customer', 'ops', 'كود الاستلام مع المشتري مش مع المستلم', { short: 'الكود فين؟',
  what: 'الكود بيظهر في تطبيق المشتري بس، واللي واقف على الباب هو المستلم.', why: 'يا إما الكابتن يستنى المشتري يرد، يا إما يسلّم من غير إثبات.', ex: 'الكابتن واقف، وسعاد بتتصل بأحمد في الشغل عشان يقولها 4 أرقام.', pol: ['CUSTOMER_007'], cur: 'غير محقَّقة — المحاكي بيوضّح الفجوة.', imp: { c: 'إحراج وانتظار', m: '—', k: 'وقت ضايع', w: 'تسليم غير مثبت' }, fin: '—', risk: 'مرتفع', fix: 'الكود يوصل للمستلم مباشرة (رسالة أو مكالمة) بعد ما المشتري يوافق.', alt1: 'الكابتن يكلّم المشتري ويسجّل موافقة صوتية (محتاج رأي قانوني).', alt2: '—', need: N(1, 1, 0, 1), src: 'CUSTOMER_007 · SCN-008' });
F('r-no-account', 'unknown', 'medium', 'recipient', 'r_home', 18, 'Customer', 'ux', 'المستلم ما يقدرش يشتكي ولا يقيّم', { short: 'المستلم بلا حساب',
  what: 'المستلم يقدر يستلم أو يرفض بس. أي حاجة تانية — شكوى، إلغاء، بديل، فلوس — بترجع للمشتري.', why: 'لو الأكل وصل بايظ للأم، الشكوى لازم تعدّي على الابن.', ex: 'سعاد لقت الصنف ناقص — مش عارفة تكلم مين.', pol: ['CUSTOMER_007'], cur: 'مسودة — «المشتري بيقرر، والمستلم بيستلم».', imp: { c: 'رحلة شكوى أطول', m: '—', k: '—', w: 'شكاوى متأخرة' }, fin: '—', risk: 'متوسط', fix: 'رابط شكوى للمستلم مربوط بالطلب من غير ما يعمل حساب (محتاج قرار).', alt1: 'الدعم يقبل الشكوى من رقم المستلم المسجّل في الطلب.', alt2: '—', need: N(1, 0, 0, 1), src: 'CUSTOMER_007' });

